<template>
    <canvas :id="canvaId" ref="canvas" height="80"></canvas>
</template>

<script>
import Chart from 'chart.js/auto';
import axios from 'axios';
import { markRaw } from 'vue';

export default {
    name: 'Chart',
    props: {
        canvaId: {
            type: String,
            required: true,
        },
        type: {
            type: String,
            required: false,
            default: 'bar',
        },
        options: {
            type: Object,
            required: false,
            default: () => {
                return {
                    scales: {
                        y: {
                            beginAtZero: true,
                        },
                    },
                };
            },
        },
        data: {
            type: Object,
            required: false,
            default: null,
        },
        ajaxUrl: {
            type: String,
            required: false,
            default: null,
        },
        plugins: {
            type: Array,
            default: () => [],
        },
    },
    data() {
        return {
            chartData: {
                labels: this.data ? this.data.labels : [],
                datasets: this.data ? this.data.datasets : [],
            },
            myChart: null, // Keep track of the chart instance
        }
    },
    methods: {
        renderChart() {
            const canvas = this.$refs.canvas;
            if (!canvas) {
                return;
            }

            if (this.myChart) {
                // Destroy the existing chart instance
                this.myChart.destroy();
            }

            const config = {
                type: this.type,
                data: this.chartData,
                options: this.options,
                plugins: this.plugins,
            };
            this.myChart = markRaw(new Chart(canvas, config));
        },
        async getDatasets() {
            const response = await axios.get(this.ajaxUrl);
            this.chartData.labels = response.data.labels;
            this.chartData.datasets = response.data.datasets;
            this.renderChart();
        },
    },
    mounted() {
        if (this.data) {
            this.renderChart();
        }

        if (this.ajaxUrl) {
            this.getDatasets();
        }
    },
    beforeUnmount() {
        this.myChart?.destroy();
    },
    watch: {
        plugins: {
            handler() {
                if (this.myChart) {
                    this.renderChart();
                }
            },
            deep: true,
        },
        data: {
            handler(newData, oldData) {
                if (newData) {
                    this.chartData.labels = newData.labels;
                    this.chartData.datasets = newData.datasets;
                    this.renderChart();
                }
            },
            deep: true,
        },
        ajaxUrl: {
            handler(newUrl, oldUrl) {
                if (newUrl && newUrl !== oldUrl) {
                    this.getDatasets();
                }
            },
            deep: true,
        },
    },
}

</script>

