<template>
    <Card class="card-chart" :card-header-class="`card-header-${color}`">
        <template #header>
            <slot name="chart" />
        </template>

        <h4 class="card-title">{{ title }}</h4>
        <p v-if="description || $slots.description" class="card-category">
            <slot name="description">{{ description }}</slot>
        </p>

        <template v-if="updatedText" #footer>
            <div class="stats">
                <i class="material-icons" aria-hidden="true">access_time</i>
                {{ updatedText }}
            </div>
        </template>
    </Card>
</template>

<script>
import Card from './Card.vue';

export default {
    name: 'ChartCard',
    components: { Card },
    props: {
        title: { type: String, required: true },
        color: { type: String, default: 'primary' },
        description: { type: String, default: '' },
        updatedText: { type: String, default: '' },
    },
};
</script>
